public static int[] shuffle(int[] nums) {
    int n = nums.length;
    int[] result = new int[n];
    int firstHalf = n / 2;

    for (int j = 0; j < firstHalf; j++) {
        result[j * 2] = nums[j];
        result[j * 2 + 1] = nums[firstHalf + j];
    }

    if (n % 2 == 1) {
        result[n - 1] = nums[n - 1];
    }

    return result;
}
```

